"""Unipile connection controls alongside the existing website sign-in."""

# ruff: noqa: E501
PANEL = """<section class="panel" id="linkedInCloudPanel" style="padding:18px 20px;margin-bottom:18px"><strong>LinkedIn cloud connection</strong><p id="linkedInCloudStatus" role="status">Checking connection...</p><button class="btn primary" id="connectLinkedInCloud" type="button" disabled>Connect LinkedIn</button> <button class="btn" id="refreshLinkedInCloud" type="button">Refresh connection</button> <button class="btn" id="changeLinkedInCloud" type="button" hidden>Use a different LinkedIn account</button><p class="sub">No computer pairing, worker download or software installation is needed. LinkedIn may ask for login, OTP or reconnection. Account limits still apply.</p><p class="sub" id="cloudSendingStatus">Checking cloud delivery availability...</p></section><dialog id="changeLinkedInDialog"><form id="changeLinkedInForm"><div class="modal-head"><div><h2>Change LinkedIn account</h2><p class="sub">Connect your current profile without deleting research history.</p></div><button type="button" class="close" id="closeLinkedInChange" aria-label="Close account change">x</button></div><div class="form-grid"><div class="field full"><label for="newLinkedInProfile">New LinkedIn profile URL</label><input id="newLinkedInProfile" type="url" maxlength="2048" required placeholder="https://www.linkedin.com/in/your-profile/"></div><div class="field full"><p class="sub">You will authenticate through Unipile. The current account stays linked until the exact new profile is verified. Leads, campaigns and history remain in this workspace. Previously authorized deliveries stay bound to the old sender and are not transferred.</p><label><input id="confirmLinkedInChange" type="checkbox" required style="width:auto"> I confirm this profile is the new LinkedIn sender for this workspace.</label></div></div><div class="modal-actions"><span id="linkedInChangeError" class="sub" role="status"></span><button type="submit" class="btn primary" id="submitLinkedInChange">Connect new account</button></div></form></dialog>"""
SCRIPT = """<script>document.addEventListener('DOMContentLoaded',()=>{
const connect=document.getElementById('connectLinkedInCloud'),status=document.getElementById('linkedInCloudStatus');
async function state(refresh=false){try{const r=await fetch('/api/cloud/'+(refresh?'refresh':'account'),refresh?{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}:{}),v=await r.json();if(!r.ok)throw Error(v.detail||'Connection check failed');status.textContent=v.message;document.getElementById('cloudSendingStatus').textContent=v.sending_enabled?'Cloud requests and messages require reviewing and enabling the exact draft in Outreach. Follow-ups wait for confirmed first-degree acceptance.':'Cloud sending is not enabled by the app owner.';connect.disabled=!v.configured;connect.textContent=(v.connected||v.has_linked_account)?'Reconnect LinkedIn':'Connect LinkedIn';document.getElementById('changeLinkedInCloud').hidden=!v.can_change_account;await refreshSearch();}catch(e){status.textContent=e.message;}}
connect.onclick=async()=>{connect.disabled=true;try{const r=await fetch('/api/cloud/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}),v=await r.json();if(!r.ok)throw Error(v.detail||'Could not connect LinkedIn');location.assign(v.url);}catch(e){status.textContent=e.message;connect.disabled=false;}};
document.getElementById('changeLinkedInCloud').onclick=()=>{document.getElementById('linkedInChangeError').textContent='';document.getElementById('changeLinkedInDialog').showModal();};
document.getElementById('closeLinkedInChange').onclick=()=>document.getElementById('changeLinkedInDialog').close();
document.getElementById('changeLinkedInForm').onsubmit=async e=>{e.preventDefault();const button=document.getElementById('submitLinkedInChange');button.disabled=true;try{const r=await fetch('/api/cloud/change-account',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed:document.getElementById('confirmLinkedInChange').checked,profile_url:document.getElementById('newLinkedInProfile').value})}),v=await r.json();if(!r.ok)throw Error(typeof v.detail==='string'?v.detail:'Check the profile URL and confirmation.');location.assign(v.url);}catch(error){document.getElementById('linkedInChangeError').textContent=error.message;button.disabled=false;}};
document.getElementById('refreshLinkedInCloud').onclick=()=>state(true);state();
});</script>"""
